def solve(hollow_square_input):
    """
    Apply the transformation pattern observed in the demo.

    Pattern: 
    - Keep outer border of 5s as-is
    - Add inner rectangular frame of 2s spanning 1 cell inward on each side
    - Fill remaining interior with 5s
    """
    h = len(hollow_square_input)
    w = len(hollow_square_input[0])

    # Find the bounding box of non-zero values
    min_r, max_r, min_c, max_c = h, h, w, w
    for i in range(h):
        for j in range(w):
            if hollow_square_input[i][j] != 0:
                min_r, max_r = min(min_r, i), max(max_r, i)
                min_c, max_c = min(min_c, j), max(max_c, j)

    # Create output initialized with 0s
    out = [[0 for _ in range(w)] for _ in range(h)]

    # Copy outer border
    for i in range(min_r, max_r + 1):
        for j in range(min_c, max_c + 1):
            if i == min_r or i == max_r or j == min_c or j == max_c:
                out[i][j] = hollow_square_input[i][j]

    # Add inner frame of 2s (one layer inward from outer border)
    for i in range(min_r + 1, max_r):
        for j in range(min_c + 1, max_c):
            if i == min_r + 1 or i == max_r - 1 or j == min_c + 1 or j == max_c - 1:
                out[i][j] = 2

    # Fill remaining interior with 5s
    for i in range(min_r + 2, max_r - 1):
        for j in range(min_c + 2, max_c - 1):
            out[i][j] = 5

    return out

